pub const BucketId = enum { one, two };
pub const Result = struct { moves: u64, goal_bucket: BucketId, other_bucket: u64 };

pub fn measure(bucket_one: u64, bucket_two: u64, goal: u64, start_bucket: BucketId) ?Result {
    // early impossible checks
    if (goal > bucket_one and goal > bucket_two) {
        return null;
    }
    // If goal equals one of the capacities, we could just fill that bucket (if start bucket is that bucket? Actually we need to consider rule)
    // BFS will handle.

    const allocator = std.heap.page_allocator;

    // visited map
    var visited = std.AutoHashMap(StructKey, void){};
    try visited.ensureTotalCapacity(allocator, 1024); // preallocate maybe

    const StructKey = struct { a: u64, b: u64 };

    // queue
    var queue = std.Queue(State).init(allocator);
    defer queue.deinit();

    // start state
    const start_a: u64, start_b: u64;
    if (start_bucket == .one) {
        start_a = bucket_one;
        start_b = 0;
    } else {
        start_a = 0;
        start_b = bucket_two;
    }

    const start_state = State{ .a = start_a, .b = start_b, .moves = 1 };
    try visited.put(allocator, StructKey{ .a = start_a, .b = start_b }, {});
    try queue.enqueue(start_state);

    // BFS loop
    while (queue.dequeue()) |state| {
        const a = state.a;
        const b = state.b;
        const moves = state.moves;

        // check goal
        if (a == goal) {
            const result = Result{
                .moves = moves,
                .goal_bucket = .one,
                .other_bucket = b,
            };
            // cleanup visited? We'll just return; visited will be dropped.
            return result;
        }
        if (b == goal) {
            const result = Result{
                .moves = moves,
                .goal_bucket = .two,
                .other_bucket = a,
            };
            return result;
        }

        // generate actions
        // 1. Fill bucket one
        {
            const na = bucket_one;
            const nb = b;
            if (!isProhibited(start_bucket, bucket_one, bucket_two, na, nb)) {
                const key = StructKey{ .a = na, .b = nb };
                if (!visited.contains(key)) {
                    try visited.put(allocator, key, {});
                    try queue.enqueue(State{ .a = na, .b = nb, .moves = moves + 1 });
                }
            }
        }

        // 2. Fill bucket two
        {
            const na = a;
            const nb = bucket_two;
            if (!isProhibited(start_bucket, bucket_one, bucket_two, na, nb)) {
                const key = StructKey{ .a = na, .b = nb };
                if (!visited.contains(key)) {
                    try visited.put(allocator, key, {});
                    try queue.enqueue(State{ .a = na, .b = nb, .moves = moves + 1 });
                }
            }
        }

        // 3. Empty bucket one
        {
            const na = 0;
            const nb = b;
            if (!isProhibited(start_bucket, bucket_one, bucket_two, na, nb)) {
                const key = StructKey{ .a = na, .b = nb };
                if (!visited.contains(key)) {
                    try visited.put(allocator, key, {});
                    try queue.enqueue(State{ .a = na, .b = nb, .moves = moves + 1 });
                }
            }
        }

        // 4. Empty bucket two
        {
            const na = a;
            const nb = 0;
            if (!isProhibited(start_bucket, bucket_one, bucket_two, na, nb)) {
                const key = StructKey{ .a = na, .b = nb };
                if (!visited.contains(key)) {
                    try visited.put(allocator, key, {});
                    try queue.enqueue(State{ .a = na, .b = nb, .moves = moves + 1 });
                }
            }
        }

        // 5. Pour from one to two
        {
            const space = bucket_two - b;
            const pour = @min(a, space);
            const na = a - pour;
            const nb = b + pour;
            if (!isProhibited(start_bucket, bucket_one, bucket_two, na, nb)) {
                const key = StructKey{ .a = na, .b = nb };
                if (!visited.contains(key)) {
                    try visited.put(allocator, key, {});
                    try queue.enqueue(State{ .a = na, .b = nb, .moves = moves + 1 });
                }
            }
        }

        // 6. Pour from two to one
        {
            const space = bucket_one - a;
            const pour = @min(b, space);
            const na = a + pour;
            const nb = b - pour;
            if (!isProhibited(start_bucket, bucket_one, bucket_two, na, nb)) {
                const key = StructKey{ .a = na, .b = nb };
                if (!visited.contains(key)) {
                    try visited.put(allocator, key, {});
                    try queue.enqueue(State{ .a = na, .b = nb, .moves = moves + 1 });
                }
            }
        }
    }

    // cleanup visited
    visited.deinit();
    return null;
}

